const state = { count: 0 }
const listeners = new Set<(phase: string) => void>()
function observe(listener: (phase: string) => void) {
  listeners.add(listener) // 隐患：没有解绑句柄，面板关闭后仍保留观察者。
}
function increment() {
  for (const listener of listeners) listener('start') // 隐患：诊断抛错会阻止业务执行。
